import re
from typing import NamedTuple


class TemplateError(Exception):
    pass


class TemplateSyntaxError(TemplateError):
    def __init__(self, message: str, lineno: int):
        super().__init__(f"line {lineno}: {message}")
        self.message = message
        self.lineno = lineno


class TemplateRenderError(TemplateError):
    def __init__(self, message: str, lineno: int):
        super().__init__(f"line {lineno}: {message}")
        self.message = message
        self.lineno = lineno


class Token(NamedTuple):
    kind: str  # "text", "var", "block"
    value: str
    lineno: int


def tokenize(source: str) -> list[Token]:
    tokens = []
    i = 0
    n = len(source)
    current_line = 1

    # Buffer for text
    text_buf_start = 0
    text_buf_line = 1

    while i < n:
        # Check for tag starts
        if source.startswith('{{', i):
            # Flush pending text
            if i > text_buf_start:
                tokens.append(Token("text", source[text_buf_start:i], text_buf_line))

            start_idx = i
            end_idx = source.find('}}', i + 2)
            if end_idx == -1:
                raise TemplateSyntaxError("unclosed var tag", current_line)

            value = source[i+2:end_idx]
            tokens.append(Token("var", value.strip(), current_line))

            # Advance current_line by counting newlines in the tag
            tag_content = source[start_idx:end_idx+2]
            current_line += tag_content.count('\n')

            i = end_idx + 2
            # Reset text buffer start
            text_buf_start = i
            text_buf_line = current_line

        elif source.startswith('{%', i):
            # Flush pending text
            if i > text_buf_start:
                tokens.append(Token("text", source[text_buf_start:i], text_buf_line))

            start_idx = i
            end_idx = source.find('%}', i + 2)
            if end_idx == -1:
                raise TemplateSyntaxError("unclosed block tag", current_line)

            value = source[i+2:end_idx]
            tokens.append(Token("block", value.strip(), current_line))

            tag_content = source[start_idx:end_idx+2]
            current_line += tag_content.count('\n')

            i = end_idx + 2
            text_buf_start = i
            text_buf_line = current_line

        elif source.startswith('{#', i):
            # Flush pending text
            if i > text_buf_start:
                tokens.append(Token("text", source[text_buf_start:i], text_buf_line))

            start_idx = i
            end_idx = source.find('#}', i + 2)
            if end_idx == -1:
                raise TemplateSyntaxError("unclosed comment", current_line)

            # Comment produces no token. 
            # "text on two sides of a comment stays as two separate tokens"
            # We flushed before, so we just update the start of the next text buffer.

            tag_content = source[start_idx:end_idx+2]
            current_line += tag_content.count('\n')

            i = end_idx + 2
            text_buf_start = i
            text_buf_line = current_line

        else:
            if source[i-1] == '\n' and i > 0: # Check previous char if we are moving past it? 
                # Actually, simpler: if source[i] is \n, we increment line after processing it.
                pass
            i += 1
            if i <= n and i > 0 and source[i-1] == '\n':
                current_line += 1

    # Flush remaining text
    if i > text_buf_start:
        tokens.append(Token("text", source[text_buf_start:i], text_buf_line))

    return tokens
