import collections.abc
from .lexer import TemplateSyntaxError, TemplateRenderError
from .parser import (
    TextNode, VarNode, ForNode, IfNode,
    Name, Segment, StringLiteral, IntLiteral, Filter,
    CondOr, CondAnd, CondNot, CondCompare, CondValue,
    parse
)


def _to_output_text(value):
    """Converts a value to its output text representation."""
    if value is None:
        return ""
    return str(value)


class Context:
    def __init__(self, base: dict):
        self.stack = [base]

    def push(self, variables: dict):
        self.stack.append(variables)

    def pop(self):
        self.stack.pop()

    def get(self, name: str):
        for scope in reversed(self.stack):
            if name in scope:
                return scope[name]
        return None


class Template:
    def __init__(self, source: str):
        self.nodes = parse(source)

    def render(self, context: dict | None = None, **kwargs) -> str:
        if context is None:
            base_context = {}
        else:
            base_context = context  # We don't modify it, just read

        # Merge kwargs (kwargs win)
        merged = dict(base_context)
        merged.update(kwargs)

        ctx = Context(merged)
        out = []
        self._render_nodes(self.nodes, ctx, out)
        return "".join(out)

    def _render_nodes(self, nodes: list, ctx: Context, out: list):
        for node in nodes:
            self._render_node(node, ctx, out)

    def _render_node(self, node, ctx: Context, out: list):
        if isinstance(node, TextNode):
            out.append(node.text)
        elif isinstance(node, VarNode):
            value = self._eval_expr(node.expr, ctx, node.lineno)
            text = _to_output_text(value)
            if text: # None writes nothing
                out.append(text)
        elif isinstance(node, ForNode):
            self._render_for(node, ctx, out)
        elif isinstance(node, IfNode):
            self._render_if(node, ctx, out)
        else:
            raise TemplateRenderError(f"unknown node type {type(node)}", 0)

    def _render_for(self, node: ForNode, ctx: Context, out: list):
        # Evaluate iterable
        iter_val = self._eval_expr(node.expr, ctx, node.lineno)

        # Determine items
        if iter_val is None:
            items = []
        elif isinstance(iter_val, collections.abc.Mapping):
            items = list(iter_val.keys())
        elif isinstance(iter_val, (list, tuple)):
            items = iter_val
        else:
            try:
                items = list(iter_val)
            except TypeError:
                raise TemplateRenderError(f"cannot iterate over {type(iter_val)}", node.lineno)

        length = len(items)

        if length == 0:
            if node.else_body:
                self._render_nodes(node.else_body, ctx, out)
        else:
            for i, item in enumerate(items):
                # Create loop context
                loop_vars = {
                    'loop': {
                        'index': i + 1,
                        'index0': i,
                        'first': i == 0,
                        'last': i == length - 1,
                        'length': length
                    },
                    node.name: item
                }

                ctx.push(loop_vars)
                self._render_nodes(node.body, ctx, out)
                ctx.pop()

    def _render_if(self, node: IfNode, ctx: Context, out: list):
        for cond, body in node.branches:
            result = self._eval_cond(cond, ctx, node.lineno)
            if result:
                self._render_nodes(body, ctx, out)
                return

        # If no branch matched, render else
        if node.else_body:
            self._render_nodes(node.else_body, ctx, out)

    def _eval_cond(self, cond, ctx: Context, lineno: int) -> bool:
        if isinstance(cond, CondOr):
            left = self._eval_cond(cond.left, ctx, lineno)
            if left:
                return True
            return self._eval_cond(cond.right, ctx, lineno)
        elif isinstance(cond, CondAnd):
            left = self._eval_cond(cond.left, ctx, lineno)
            if not left:
                return False
            return self._eval_cond(cond.right, ctx, lineno)
        elif isinstance(cond, CondNot):
            return not self._eval_cond(cond.operand, ctx, lineno)
        elif isinstance(cond, CondCompare):
            left_val = self._eval_expr(cond.left, ctx, lineno)
            right_val = self._eval_expr(cond.right, ctx, lineno)
            return self._compare(left_val, cond.op, right_val, lineno)
        elif isinstance(cond, CondValue):
            val = self._eval_expr(cond.expr, ctx, lineno)
            return bool(val)
        else:
            raise TemplateRenderError("unknown condition node", lineno)

    def _compare(self, left, op, right, lineno):
        try:
            if op == '==':
                return left == right
            elif op == '!=':
                return left != right
            elif op == '<':
                return left < right
            elif op == '<=':
                return left <= right
            elif op == '>':
                return left > right
            elif op == '>=':
                return left >= right
            else:
                raise TemplateRenderError(f"unknown operator {op}", lineno)
        except TypeError:
            raise TemplateRenderError(f"cannot compare {type(left)} and {type(right)}", lineno)

    def _eval_expr(self, expr, ctx: Context, lineno: int):
        if isinstance(expr, Name):
            return ctx.get(expr.name)
        elif isinstance(expr, StringLiteral):
            return expr.value
        elif isinstance(expr, IntLiteral):
            return expr.value
        elif isinstance(expr, Segment):
            base = self._eval_expr(expr.base, ctx, lineno)
            return self._get_segment(base, expr.seg)
        elif isinstance(expr, Filter):
            base_val = self._eval_expr(expr.base, ctx, lineno)
            return self._apply_filter(expr.name, base_val, expr.arg, lineno)
        else:
            raise TemplateRenderError(f"unknown expression node {type(expr)}", lineno)

    def _get_segment(self, value, seg: str):
        if value is None:
            return None

        # Check if seg is integer
        if seg.isdigit():
            idx = int(seg)
            if isinstance(value, (list, tuple)):
                if 0 <= idx < len(value):
                    return value[idx]
                else:
                    return None
            # If it's a mapping, look up string key
            if isinstance(value, collections.abc.Mapping):
                return value.get(seg)
            # On other values with int segment? Spec: "anything else gives None"
            return None

        else:
            # It's a name segment
            if seg.startswith('_'):
                return None

            if isinstance(value, collections.abc.Mapping):
                return value.get(seg)

            # Attribute access
            try:
                return getattr(value, seg)
            except AttributeError:
                return None

    def _apply_filter(self, name, value, arg_node, lineno):
        # arg_node is None, StringLiteral, or IntLiteral

        if name == 'upper':
            return _to_output_text(value).upper()
        elif name == 'lower':
            return _to_output_text(value).lower()
        elif name == 'trim':
            return _to_output_text(value).strip()
        elif name == 'length':
            if value is None:
                return 0
            if isinstance(value, (list, tuple, str, collections.abc.Mapping, set)):
                return len(value)
            raise TemplateRenderError(f"length filter cannot be applied to {type(value)}", lineno)
        elif name == 'first':
            if value is None:
                return None
            if isinstance(value, (list, tuple, str)):
                return value[0] if len(value) > 0 else None
            raise TemplateRenderError(f"first filter cannot be applied to {type(value)}", lineno)
        elif name == 'last':
            if value is None:
                return None
            if isinstance(value, (list, tuple, str)):
                return value[-1] if len(value) > 0 else None
            raise TemplateRenderError(f"last filter cannot be applied to {type(value)}", lineno)
        elif name == 'reverse':
            if value is None:
                return None
            if isinstance(value, str):
                return value[::-1]
            if isinstance(value, (list, tuple)):
                return list(reversed(value))
            raise TemplateRenderError(f"reverse filter cannot be applied to {type(value)}", lineno)
        elif name == 'join':
            # arg_node must be StringLiteral
            if arg_node is None or not isinstance(arg_node, StringLiteral):
                raise TemplateRenderError("join filter requires string argument", lineno)
            sep = arg_node.value
            if value is None:
                return ""
            if isinstance(value, (list, tuple)):
                return sep.join(_to_output_text(item) for item in value)
            raise TemplateRenderError(f"join filter cannot be applied to {type(value)}", lineno)
        elif name == 'default':
            # arg_node must be StringLiteral or IntLiteral
            if value is None or value == "":
                if isinstance(arg_node, StringLiteral):
                    return arg_node.value
                elif isinstance(arg_node, IntLiteral):
                    return arg_node.value
                else:
                    raise TemplateRenderError("default filter requires string or int argument", lineno)
            return value
        elif name == 'truncate':
            # arg_node must be IntLiteral
            if arg_node is None or not isinstance(arg_node, IntLiteral):
                raise TemplateRenderError("truncate filter requires integer argument", lineno)
            n = arg_node.value
            if n < 0:
                # This is a syntax error according to spec, but caught here if parser missed it?
                # Spec says: "a negative truncate is a syntax error".
                # We should catch this in parser. But if we reach here, it's a bug in parser or 
                # the parser allowed it. 
                # Let's check parser: 
                # parse_value_expression -> parse_filter_arg -> parse_int.
                # It doesn't check for negative. 
                # We should add check in parser for negative truncate.
                # For now, raise render error as fallback, but ideally parser should fail.
                raise TemplateRenderError("truncate argument must be non-negative", lineno)
           s = _to_output_text(value)
            if len(s) > n:
                return s[:n] + "..."
            return s
        elif name == 'items':
            if value is None:
                return []
            if isinstance(value, collections.abc.Mapping):
                return list(value.items())
            raise TemplateRenderError(f"items filter cannot be applied to {type(value)}", lineno)
        else:
            raise TemplateRenderError(f"unknown filter {name}", lineno)


def render(source: str, context: dict | None = None, **kwargs) -> str:
    return Template(source).render(context, **kwargs)
