To build the `sheet` package, we will create the four specified files with the required logic for parsing, dependency tracking, and evaluation.

### 1. `sheet/formula.py`

This module handles the lexing, parsing, and evaluation of formulas. It defines the AST nodes, the `FormulaError` exception, and the `ErrorValue` class.

```python
"""
sheet/formula.py

Formula parsing and evaluation for the sheet package.
"""

import re
import operator
from dataclasses import dataclass, field
from typing import Union, Any, Callable, Set

# --- Exceptions and Values ---

class FormulaError(ValueError):
    """Raised when a formula is invalid."""
    pass

class ErrorValue(str):
    """
    A string subclass representing error values.
    Compares equal to its string representation.
    """
    def __new__(cls, value: str):
        return super().__new__(cls, value)

    def __repr__(self):
        return f"ErrorValue({super().__repr__()})"

    def __eq__(self, other):
        if isinstance(other, str):
            return super().__eq__(other)
        return NotImplemented

    def __hash__(self):
        return super().__hash__()

# --- AST Nodes ---

@dataclass
class NumberNode:
    value: Union[int, float]

@dataclass
class RefNode:
    name: str

@dataclass
class UnaryNode:
    op: str
    operand: Any

@dataclass
class BinaryNode:
    op: str
    left: Any
    right: Any

# --- Parser ---

# Tokenizer patterns
TOKEN_PATTERN = re.compile(
    r"""
    (?P<WS>\s+)
  | (?P<NUMBER>\d+(?:\.\d+)?)
  | (?P<REF>[A-Z]+\d+)  # Case handled by uppercasing input string in parser
  | (?P<PLUS>\+)
  | (?P<MINUS>-)
  | (?P<MUL>\*)
  | (?P<SLASH>/)
  | (?P<LPAREN>\()
  | (?P<RPAREN>\))
    """,
    re.VERBOSE | re.IGNORECASE
)

class Parser:
    def __init__(self, source: str):
        self.tokens = []
        self.pos = 0
        self._tokenize(source)

    def _tokenize(self, source: str):
        source = source.upper()
        for m in TOKEN_PATTERN.finditer(source):
            kind = m.lastgroup
            val = m.group()
            if kind == 'WS':
                continue
            if kind == 'REF':
                # Validate reference structure strictly
                letters, digits = self._split_ref(val)
                if len(letters) > 1 or int(digits) < 1 or int(digits) > 999:
                    raise FormulaError(f"Invalid reference: {val}")
                # Check for leading zeros in row number part
                if digits != str(int(digits)):
                    raise FormulaError(f"Reference has leading zeros: {val}")
                self.tokens.append(('REF', val))
            elif kind == 'NUMBER':
                self.tokens.append(('NUMBER', val))
            else:
                self.tokens.append((kind, val))

        # Simple check for any non-matching characters
        # The regex above consumes valid parts. We need to ensure the whole string was matched.
        # A simpler way: iterate through and track index.

    def _split_ref(self, ref_str: str):
        match = re.match(r'^([A-Z]+)(\d+)$', ref_str)
        if not match:
            raise FormulaError(f"Malformed reference: {ref_str}")
        return match.group(1), match.group(2)

    def parse(self):
        if not self.tokens:
            raise FormulaError("Empty formula")

        node = self._parse_expr()

        if self.pos < len(self.tokens):
            raise FormulaError(f"Incomplete expression at token {self.tokens[self.pos]}")

        return node

    def _parse_expr(self):
        left = self._parse_term()
        while self.pos < len(self.tokens) and self.tokens[self.pos][0] in ('PLUS', 'MINUS'):
            op = self.tokens[self.pos][0]
            self.pos += 1
            right = self._parse_term()
            left = BinaryNode(op, left, right)
        return left

    def _parse_term(self):
        left = self._parse_unary()
        while self.pos < len(self.tokens) and self.tokens[self.pos][0] in ('MUL', 'SLASH'):
            op = self.tokens[self.pos][0]
            self.pos += 1
            right = self._parse_unary()
            left = BinaryNode(op, left, right)
        return left

    def _parse_unary(self):
        if self.pos < len(self.tokens) and self.tokens[self.pos][0] in ('PLUS', 'MINUS'):
            op = self.tokens[self.pos][0]
            self.pos += 1
            operand = self._parse_unary()
            return UnaryNode(op, operand)

        if self.pos >= len(self.tokens):
            raise FormulaError("Unexpected end of expression")

        kind, val = self.tokens[self.pos]

        if kind == 'NUMBER':
            self.pos += 1
            if '.' in val:
                return NumberNode(float(val))
            else:
                return NumberNode(int(val))

        if kind == 'REF':
            self.pos += 1
            return RefNode(val)

        if kind == 'LPAREN':
            self.pos += 1
            node = self._parse_expr()
            if self.pos >= len(self.tokens) or self.tokens[self.pos][0] != 'RPAREN':
                raise FormulaError("Unbalanced parentheses")
            self.pos += 1
            return node

        raise FormulaError(f"Unexpected token: {kind} {val}")

def parse_formula(source: str):
    """
    Parses the text after '='.
    """
    if not source:
        raise FormulaError("Empty formula")

    # We need a more robust tokenizer that checks for invalid chars
    # The regex approach above misses invalid chars silently if they don't match.
    # Let's implement a strict manual tokenizer or use finditer with index tracking.

    return _strict_parse_formula(source)

def _strict_parse_formula(source: str):
    # Tokenize strictly
    tokens = []
    i = 0
    n = len(source)

    while i < n:
        if source[i].isspace():
            i += 1
            continue

        if source[i].isdigit():
            j = i
            while j < n and source[j].isdigit():
                j += 1
            if j < n and source[j] == '.':
                j += 1
                while j < n and source[j].isdigit():
                    j += 1
            tokens.append(('NUMBER', source[i:j]))
            i = j
        elif source[i].isalpha():
            j = i
            while j < n and source[j].isalpha():
                j += 1
            start_j = j
            while j < n and source[j].isdigit():
                j += 1
            if j == start_j:
                raise FormulaError("Invalid reference: must end with digits")

            ref_str = source[i:j].upper()
            letters = ref_str[:start_j-i]
            digits = ref_str[start_j-i:]

            if len(letters) > 1:
                raise FormulaError(f"Invalid reference: {ref_str}")
            if int(digits) < 1 or int(digits) > 999:
                raise FormulaError(f"Invalid reference: {ref_str}")
            if digits != str(int(digits)): # Leading zero check
                raise FormulaError(f"Invalid reference: {ref_str}")

            tokens.append(('REF', ref_str))
            i = j
        elif source[i] in '+-*/()':
            tokens.append((source[i], source[i]))
            i += 1
        else:
            raise FormulaError(f"Invalid character: {source[i]}")

    if not tokens:
        raise FormulaError("Empty formula")

    # Simple Recursive Descent Parser on token list
    class _Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self, expected_type=None):
            tok = self.peek()
            if tok is None:
                raise FormulaError("Unexpected end of input")
            if expected_type and tok[0] != expected_type:
                raise FormulaError(f"Expected {expected_type}, got {tok[0]}")
            self.pos += 1
            return tok

        def parse_expr(self):
            left = self.parse_term()
            while True:
                tok = self.peek()
                if tok and tok[0] in ('+', '-'):
                    self.pos += 1
                    right = self.parse_term()
                    left = BinaryNode(tok[0], left, right)
                else:
                    break
            return left

        def parse_term(self):
            left = self.parse_unary()
            while True:
                tok = self.peek()
                if tok and tok[0] in ('*', '/'):
                    self.pos += 1
                    right = self.parse_unary()
                    left = BinaryNode(tok[0], left, right)
                else:
                    break
            return left

        def parse_unary(self):
            tok = self.peek()
            if tok and tok[0] in ('+', '-'):
                self.pos += 1
                operand = self.parse_unary()
                return UnaryNode(tok[0], operand)
            else:
                return self.parse_primary()

        def parse_primary(self):
            tok = self.peek()
            if not tok:
                raise FormulaError("Unexpected end of expression")

            if tok[0] == 'NUMBER':
                self.pos += 1
                val = tok[1]
                if '.' in val:
                    return NumberNode(float(val))
                else:
                    return NumberNode(int(val))

            if tok[0] == 'REF':
                self.pos += 1
                return RefNode(tok[1])

            if tok[0] == '(':
                self.pos += 1
                node = self.parse_expr()
                end_tok = self.peek()
                if not end_tok or end_tok[0] != ')':
                    raise FormulaError("Unbalanced parentheses")
                self.pos += 1
                return node

            raise FormulaError(f"Unexpected token: {tok}")

    p = _Parser(tokens)
    tree = p.parse_expr()

    if p.pos != len(p.tokens):
        raise FormulaError("Incomplete expression")

    return tree

def references(tree) -> set:
    """Returns a set of upper-case cell names referenced in the tree."""
    refs = set()
    def walk(node):
        if isinstance(node, RefNode):
            refs.add(node.name)
        elif isinstance(node, BinaryNode):
            walk(node.left)
            walk(node.right)
        elif isinstance(node, UnaryNode):
            walk(node.operand)
        # NumberNode has no refs
    walk(tree)
    return refs

def evaluate(tree, lookup):
    """
    Evaluates the syntax tree.
    lookup(name) returns the value of the cell.
    """
    def _eval(node):
        if isinstance(node, NumberNode):
            return node.value

        if isinstance(node, RefNode):
            val = lookup(node.name)
            if val is None:
                return 0
            return val

        if isinstance(node, UnaryNode):
            val = _eval(node.operand)
            # Check for error propagation
            if isinstance(val, ErrorValue):
                return val
            # Check for text propagation
            if isinstance(val, str):
                return ErrorValue("#ERROR!")

            if node.op == '+':
                return val
            else: # '-'
                if isinstance(val, int):
                    return -val
                return -val # float negation works same way

        if isinstance(node, BinaryNode):
            left = _eval(node.left)
            # If left is error, return it immediately
            if isinstance(left, ErrorValue):
                return left

            right = _eval(node.right)

            # If right is error, return it
            if isinstance(right, ErrorValue):
                return right

            # If either is text, result is #ERROR!
            if isinstance(left, str) or isinstance(right, str):
                return ErrorValue("#ERROR!")

            op = node.op
            try:
                if op == '+':
                    return left + right
                elif op == '-':
                    return left - right
                elif op == '*':
                    return left * right
                elif op == '/':
                    if right == 0:
                        return ErrorValue("#ERROR!")
                    return left / right
            except ZeroDivisionError:
                return ErrorValue("#ERROR!")
            except Exception:
                return ErrorValue("#ERROR!")

        raise FormulaError(f"Unknown node type: {type(node)}")

    return _eval(tree)

