        self.position = position
        if message:
            super().__init__(message)
        else:
            super().__init__(f"CalcError at position {position}")


class TokenType(Enum):
    NUMBER = auto()
    PLUS = auto()
    MINUS = auto()
    MULTIPLY = auto()
    DIVIDE = auto()
    LPAREN = auto()
    RPAREN = auto()


@dataclass
class Token:
    type: TokenType
    value: object
    position: int


def _tokenize(expr: str) -> list[Token]:
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]
        # Skip whitespace (spaces and tabs)
        if ch in (' ', '\t'):
            i += 1
            continue
        # Parse numbers: digits, optionally followed by . and more digits
        if ch.isdigit():
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            # Check for decimal point
            if i < n and expr[i] == '.':
                # Ensure there are digits after the decimal point
                if i + 1 < n and expr[i + 1].isdigit():
                    i += 1  # skip the '.'
                    while i < n and expr[i].isdigit():
                        i += 1
                else:
                    # Invalid: '.' at end of number without following digits
                    raise CalcError(i, f"Invalid number syntax at position {i}")
            # Check for another '.' which would make it invalid (e.g., 1.5.2)
            if i < n and expr[i] == '.':
                raise CalcError(i, f"Invalid number syntax at position {i}")
            number_str = expr[start:i]
            tokens.append(Token(TokenType.NUMBER, Fraction(number_str), start))
        elif ch == '.':
            # Invalid: number starting with '.' (e.g., .5)
            raise CalcError(i, f"Invalid number syntax at position {i}")
        elif ch == '+':
            tokens.append(Token(TokenType.PLUS, '+', i))
            i += 1
        elif ch == '-':
            tokens.append(Token(TokenType.MINUS, '-', i))
            i += 1
        elif ch == '*':
            tokens.append(Token(TokenType.MULTIPLY, '*', i))
            i += 1
        elif ch == '/':
            tokens.append(Token(TokenType.DIVIDE, '/', i))
            i += 1
        elif ch == '(':
            tokens.append(Token(TokenType.LPAREN, '(', i))
            i += 1
        elif ch == ')':
            tokens.append(Token(TokenType.RPAREN, ')', i))
            i += 1
        else:
            # Invalid character
            raise CalcError(i, f"Invalid character '{ch}' at position {i}")

    return tokens


