        """Handle + and - (lowest precedence, left-associative)."""
        result = self.parse_term()
        while self.peek() is not None and self.peek().type in (TokenType.PLUS, TokenType.MINUS):
            op = self.advance()
            right = self.parse_term()
            if op.type == TokenType.PLUS:
                result = result + right
            else:
                result = result - right
        return result

    def parse_term(self) -> Fraction:
        """Handle * and / (higher precedence, left-associative)."""
        result = self.parse_unary()
        while self.peek() is not None and self.peek().type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            op = self.advance()
            right = self.parse_unary()
            if op.type == TokenType.MULTIPLY:
