import heapq
from collections.abc import Iterable


class CycleError(ValueError):
    def __init__(self, cycle: list[str]):
        self.cycle = cycle
        super().__init__("Dependency cycle detected: " + " -> ".join(cycle))


def normalize_graph(graph: dict[str, Iterable[str]]) -> dict[str, set[str]]:
    all_nodes: set[str] = set(graph.keys())
    for deps in graph.values():
        all_nodes.update(deps)

    normalized: dict[str, set[str]] = {}
    for node in all_nodes:
        if node in graph:
            normalized[node] = set(graph[node])
        else:
            normalized[node] = set()
    return normalized


def toposort(graph: dict[str, Iterable[str]]) -> list[str]:
    normalized = normalize_graph(graph)

    # Build reverse adjacency and in-degrees
    in_degree = {node: len(deps) for node, deps in normalized.items()}
    dependents: dict[str, list[str]] = {node: [] for node in normalized}
    for node, deps in normalized.items():
        for dep in deps:
            dependents[dep].append(node)

    # Initialize heap with nodes that have no dependencies
    heap = [node for node, deg in in_degree.items() if deg == 0]
    heapq.heapify(heap)

    result: list[str] = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    # Check for cycle
    if len(result) != len(normalized):
        remaining = set(normalized) - set(result)
        start = min(remaining)
        path: list[str] = []
        visited_in_path: dict[str, int] = {}
        current = start
        while True:
            if current in visited_in_path:
                idx = visited_in_path[current]
                cycle = path[idx:]
                break
            visited_in_path[current] = len(path)
            path.append(current)
            deps_in_remaining = sorted(d for d in normalized[current] if d in remaining)
            current = deps_in_remaining[0]
        raise CycleError(cycle)

    return result
