sheet/formula.py
"""Formula parsing and evaluation for the sheet package."""


class ErrorValue(str):
    """A special string value representing an error in a cell."""
    pass


# Canonical error instances
ErrorValue.ERROR = ErrorValue("#ERROR!")
ErrorValue.CYCLE = ErrorValue("#CYCLE!")


class FormulaError(ValueError):
    """Raised when a formula cannot be parsed."""
    pass


# --- AST node classes ---

class Number:
    """A numeric literal in the formula."""
    __slots__ = ("value",)

    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return f"Number({self.value!r})"


class Ref:
    """A cell reference in the formula."""
    __slots__ = ("name",)

    def __init__(self, name):
        self.name = name

    def __repr__(self):
        return f"Ref({self.name!r})"


class BinOp:
    """A binary operator node (+, -, *, /)."""
    __slots__ = ("op", "left", "right")

    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right

    def __repr__(self):
        return f"BinOp({self.op!r}, {self.left!r}, {self.right!r})"


class UnaryOp:
    """A unary operator node (+, -)."""
    __slots__ = ("op", "operand")

    def __init__(self, op, operand):
        self.op = op
        self.operand = operand

    def __repr__(self):
        return f"UnaryOp({self.op!r}, {self.operand!r})"


def parse_formula(source: str):
    """Parse the text after '=' and return a syntax tree.

    Raises FormulaError for any invalid input.
    """
    if source is None:
        raise FormulaError("Formula source must be a string")
    if not source.strip():
        raise FormulaError("Empty formula")

    s = source
    n = len(s)
    pos = 0

    def skip_ws():
        nonlocal pos
        while pos < n and s[pos].isspace():
            pos += 1

    def parse_expr():
        node = parse_term()
        while True:
            skip_ws()
            if pos < n and s[pos] in ('+', '-'):
                op = s[pos]
                pos += 1
                right = parse_term()
                node = BinOp(op, node, right)
            else:
                break
        return node

    def parse_term():
        node = parse_unary()
        while True:
            skip_ws()
            if pos < n and s[pos] in ('*', '/'):
                op = s[pos]
                pos += 1
                right = parse_unary()
                node = BinOp(op, node, right)
            else:
                break
        return node

    def parse_unary():
        skip_ws()
        if pos < n and s[pos] in ('+', '-'):
            op = s[pos]
            pos += 1
            operand = parse_unary()
            return UnaryOp(op, operand)
        return parse_primary()

    def parse_primary():
        skip_ws()
        if pos >= n:
            raise FormulaError("Unexpected end of formula")
        c = s[pos]
        if c == '(':
            pos += 1
            node = parse_expr()
            skip_ws()
            if pos >= n or s[pos] != ')':
                raise FormulaError("Unbalanced parentheses")
            pos += 1
            return node
        elif c.isdigit():
            return parse_number()
        elif c.isalpha():
            return parse_ref()
        else:
            raise FormulaError(f"Unexpected character: {c!r}")

    def parse_number():
        nonlocal pos
        start = pos
        while pos < n and s[pos].isdigit():
            pos += 1
        if pos < n and s[pos] == '.':
            pos += 1
            if pos >= n or not s[pos].isdigit():
                raise FormulaError("Invalid number: expected digit after '.'")
            while pos < n and s[pos].isdigit():
                pos += 1
            return Number(float(s[start:pos]))
        else:
            return Number(int(s[start:pos]))

    def parse_ref():
        nonlocal pos
        start = pos
        # Match one or more letters
        while pos < n and s[pos].isalpha():
            pos += 1
        if pos == start:
            raise FormulaError("Expected a reference")
        # Must be followed by digits
        if pos >= n or not s[pos].isdigit():
            raise FormulaError("Invalid reference: expected digits after column letter(s)")
        while pos < n and s[pos].isdigit():
            pos += 1
        text = s[start:pos]

        # Find where letters end and digits begin
        letter_end = 0
        while letter_end < len(text) and text[letter_end].isalpha():
            letter_end += 1
        letters = text[:letter_end].upper()
        digits = text[letter_end:]

        # Validate: exactly one letter A-Z
        if len(letters) != 1:
            raise FormulaError(f"Invalid reference: {text!r}")
        col = letters[0]
        if col < 'A' or col > 'Z':
            raise FormulaError(f"Invalid reference: {text!r}")
        # Validate: no leading zeros in row
        if digits[0] == '0' and len(digits) > 1:
            raise FormulaError(f"Invalid reference: {text!r}")
        row = int(digits)
        if row < 1 or row > 999:
            raise FormulaError(f"Invalid reference: {text!r}")

        return Ref(col + digits)

    tree = parse_expr()
    skip_ws()
    if pos != n:
        raise FormulaError(f"Unexpected trailing content: {s[pos:]!r}")
    return tree


def references(tree) -> set:
    """Return a set of upper-case cell names referenced in the formula tree."""
    result = set()

    def walk(node):
        if isinstance(node, Ref):
            result.add(node.name)
        elif isinstance(node, Number):
            pass
        elif isinstance(node, UnaryOp):
            walk(node.operand)
        elif isinstance(node, BinOp):
            walk(node.left)
            walk(node.right)

    walk(tree)
    return result


def evaluate(tree, lookup):
    """Compute the formula's value.

    lookup(name) takes an upper-case cell name and returns that cell's current value.
    """

    def eval_node(node):
        if isinstance(node, Number):
            return node.value
        elif isinstance(node, Ref):
            val = lookup(node.name)
            if val is None:
                return 0
            return val
        elif isinstance(node, UnaryOp):
            operand_val = eval_node(node.operand)
            if isinstance(operand_val, ErrorValue):
                return operand_val
            if isinstance(operand_val, str):
                return ErrorValue.ERROR
            if node.op == '+':
                return operand_val
            else:  # '-'
                return -operand_val
        elif isinstance(node, BinOp):
            left_val = eval_node(node.left)
            right_val = eval_node(node.right)
            # Error propagation: left error takes precedence
            if isinstance(left_val, ErrorValue):
                return left_val
            if isinstance(right_val, ErrorValue):
                return right_val
            # Text operand -> #ERROR!
            if isinstance(left_val, str) or isinstance(right_val, str):
                return ErrorValue.ERROR
            # Arithmetic
            if node.op == '+':
                return left_val + right_val
            elif node.op == '-':
                return left_val - right_val
            elif node.op == '*':
                return left_val * right_val
            elif node.op == '/':
                if right_val == 0:
                    return ErrorValue.ERROR
                return left_val / right_val
            else:
                raise FormulaError(f"Unknown operator: {node.op!r}")
        else:
            raise FormulaError(f"Unknown node type: {type(node).__name__}")

    return eval_node(tree)
