class DependencyGraph:
    """Records dependencies between cells in a spreadsheet."""

    def __init__(self):
        # Map: cell -> set of cells it depends on (precedents)
        self._prec = {}
        # Map: cell -> set of cells that depend on it (dependents)
        self._dep = {}

    def set_dependencies(self, cell: str, precedents):
        """Replaces the precedents for a cell and updates the reverse dependents map.

        Args:
            cell: The name of the cell.
            precedents: An iterable of cell names that `cell` depends on.
        """
        # Convert to a set to handle duplicates and ensure hashable types
        new_precs = set(precedents)

        # 1. Remove old dependencies
        if cell in self._prec:
            old_precs = self._prec[cell]
            for p in old_precs:
                if p in self._dep:
                    self._dep[p].discard(cell)
                    # Clean up empty sets to keep memory footprint low
                    if not self._dep[p]:
                        del self._dep[p]
            # Clean up old prec entry
            if not old_precs:
                del self._prec[cell]
            else:
                # The old_precs set object is no longer referenced by self._prec if we reassign, 
                # but we already iterated. We will overwrite self._prec[cell] below.
                pass 

        # 2. Set new dependencies
        if new_precs:
            self._prec[cell] = new_precs
            for p in new_precs:
                if p not in self._dep:
                    self._dep[p] = set()
                self._dep[p].add(cell)
        else:
            # If no precedents, ensure cell is not in _prec (already handled if it was, but just in case)
            if cell in self._prec:
                del self._prec[cell]

    def precedents(self, cell: str) -> set[str]:
        """Returns the set of cells that `cell` directly depends on."""
        return self._prec.get(cell, set())

    def dependents(self, cell: str) -> set[str]:
        """Returns the set of cells that directly depend on `cell`."""
        return self._dep.get(cell, set())

    def all_dependents(self, cell: str) -> set[str]:
        """Returns all cells that depend on `cell` directly or transitively.

        Includes `cell` itself only if it is part of a cycle.
        """
        visited = set()
        stack = list(self._dep.get(cell, set()))

        while stack:
            current = stack.pop()
            if current in visited:
                continue
            visited.add(current)

            # If we hit the start cell again, it's a cycle, and it's already added to visited.
            # We continue to process its dependents as well.
            for dep in self._dep.get(current, set()):
                if dep not in visited:
                    stack.append(dep)

        # The logic above adds all reachable nodes to `visited`.
        # If `cell` is on a cycle, it will be reachable from itself, so it will be in `visited`.
        # If `cell` is NOT on a cycle, it will NOT be in `visited` (since we start from its dependents, not itself).

        return visited

    def cycle_cells(self) -> set[str]:
        """Returns the set of all cells that lie on a cycle."""
        cycles = set()
        # We need to check every cell that exists in the graph.
        # A cell exists if it has precedents or dependents.
        all_cells = set(self._prec.keys()) | set(self._dep.keys())

        for cell in all_cells:
            if cell in self.all_dependents(cell):
                cycles.add(cell)

        return cycles
