"""The Sheet class: the main user-facing spreadsheet interface."""

import re
from collections import deque

from .formula import parse_formula, references, evaluate, FormulaError, ErrorValue
from .graph import DependencyGraph


def _validate_name(name):
    """Validate and normalize a cell name to upper-case.

    Returns the upper-case cell name.
    Raises ValueError for a name outside the sheet.
    """
    if not isinstance(name, str):
        raise ValueError(f"Invalid cell name: {name!r}")
    upper = name.upper()
    # Must be exactly one letter A-Z followed by digits 1-999 with no leading zeros.
    match = re.fullmatch(r'([A-Z])([0-9]+)', upper)
    if not match:
        raise ValueError(f"Invalid cell name: {name!r}")
    col, row_str = match.group(1), match.group(2)
    if len(row_str) > 1 and row_str[0] == '0':
        raise ValueError(f"Invalid cell name: {name!r}")
    row = int(row_str)
    if row < 1 or row > 999:
        raise ValueError(f"Invalid cell name: {name!r}")
    return col + str(row)


def _row_major_key(name):
    """Sort key for row-major order: by row number, then column letter."""
    return (int(name[1:]), name[0])


class Sheet:
    """A spreadsheet with columns A-Z and rows 1-999."""

    def __init__(self):
        self._raw = {}      # cell name -> raw input string
        self._values = {}   # cell name -> computed value
        self._trees = {}    # cell name -> parsed formula tree (None if not a formula)
        self._graph = DependencyGraph()
        self.evaluations = 0

    def set(self, name, raw):
        """Store the cell's input and recalculate affected cells.

        Returns the cells whose value may have changed, in row-major order.
        """
        if not isinstance(raw, str):
            raise TypeError("raw must be a str")
        cell = _validate_name(name)

        if raw == '':
            # Empty the cell.
            self._graph.set_dependencies(cell, set())
            self._raw[cell] = ''
            self._values[cell] = None
            self._trees[cell] = None
            affected = {cell} | self._graph.all_dependents(cell)
            self._recalculate(affected)
            return sorted(affected, key=_row_major_key)

        if raw.startswith('='):
            # Formula: parse it (raises FormulaError if invalid, leaving sheet unchanged).
            tree = parse_formula(raw[1:])
            refs = references(tree)

            self._raw[cell] = raw
            self._trees[cell] = tree
            self._graph.set_dependencies(cell, refs)

            affected = {cell} | self._graph.all_dependents(cell)
            self._recalculate(affected)
            return sorted(affected, key=_row_major_key)

        # Number or plain text.
        stripped = raw.strip()
        if re.fullmatch(r'-?[0-9]+(\.[0-9]+)?', stripped):
            value = float(stripped) if '.' in stripped else int(stripped)
        else:
            value = raw

        self._graph.set_dependencies(cell, set())
        self._raw[cell] = raw
        self._values[cell] = value
        self._trees[cell] = None

        affected = {cell} | self._graph.all_dependents(cell)
        self._recalculate(affected)
        return sorted(affected, key=_row_major_key)

    def _recalculate(self, affected):
        """Recalculate the given set of cells.

        Cycle cells get #CYCLE!; non-cycle formula cells are evaluated exactly
        once in an order where all their precedents (within the affected set)
        are already up to date.
        """
        cycle_cells = self._graph.cycle_cells()

        # Mark cycle cells with the cycle error.
        for cell in affected:
            if cell in cycle_cells:
                self._values[cell] = ErrorValue.CYCLE

        # Collect formula cells in the affected set that are not on a cycle.
        formula_cells = {
            cell for cell in affected
            if cell in self._trees and self._trees[cell] is not None
            and cell not in cycle_cells
        }
        if not formula_cells:
            return

        # Topological sort (Kahn's algorithm) over the subgraph induced by
        # formula_cells: an edge prec -> cell exists when cell depends on prec
        # and both are in formula_cells.
        in_degree = {cell: 0 for cell in formula_cells}
        adj = {cell: [] for cell in formula_cells}
        for cell in formula_cells:
            for prec in self._graph.precedents(cell):
                if prec in formula_cells:
                    in_degree[cell] += 1
                    adj[prec].append(cell)

        queue = deque(cell for cell in formula_cells if in_degree[cell] == 0)
        order = []
        while queue:
            cell = queue.popleft()
            order.append(cell)
            for neighbor in adj[cell]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        # Evaluate in topological order.
        for cell in order:
            tree = self._trees[cell]
            value = evaluate(tree, self._values.get)
            self._values[cell] = value
            self.evaluations += 1

    def get(self, name):
        """Return the cell's current value (None for an empty cell)."""
        cell = _validate_name(name)
        return self._values.get(cell)

    def raw(self, name):
        """Return the input last stored for the cell ('' for an empty cell)."""
        cell = _validate_name(name)
        return self._raw.get(cell, '')

    def cells(self):
        """Return non-empty cell names in row-major order."""
        return sorted(
            (cell for cell in self._raw if self._raw[cell] != ''),
            key=_row_major_key,
        )
